'use strict';

// MODULES //

var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var contains = require( '@stdlib/array/base/assert/contains' ).factory;


// VARIABLES //

/**
* Regular expression to test whether a string is a valid JavaScript identifier.
*
* @private
* @constant
* @type {RegExp}
*/
var RE_IDENTIFIER = /^[a-zA-Z_$][a-zA-Z0-9_$]*$/;

/**
* Tests whether an input value is a reserved keyword.
*
* @private
* @name isReserved
* @type {Function}
* @param {string} v - value to test
* @returns {boolean} boolean indicating whether an input value is a reserved keyword
*/
var isReserved = contains( [ 'datum', 'event', 'item', 'parent' ] );


// MAIN //

/**
* Tests whether an input value is a valid Vega signal name.
*
* @param {*} v - value to test
* @returns {boolean} boolean indicating whether an input value is a valid Vega signal name
*
* @example
* var bool = isSignalName( 'width' );
* // returns true
*
* bool = isSignalName( 'height' );
* // returns true
*
* bool = isSignalName( 'foo' );
* // returns true
*
* bool = isSignalName( 'datum' );
* // returns false
*
* bool = isSignalName( '' );
* // returns false
*/
function isSignalName( v ) {
	return (
		isString( v ) &&
		RE_IDENTIFIER.test( v ) &&
		!isReserved( v )
	);
}


// EXPORTS //

module.exports = isSignalName;
